{
  "Image": {
    "Url": "{{sampleImageUrl}}"
  },
  "Context": [
    {
      "Label": "Source",
      "Text": "Photos submitted by pet adoption volunteers."
    },
    "Animals wearing orange collars are already adopted."
  ],
  "Functions": {
    "Summarize": {
      "Enable": true,
      "Key": "Summary",
      "MaxWords": 60,
      "Style": "Paragraph"
    },
    "Extract": {
      "Enable": true,
      "Mode": "Combined",
      "Fields": [
        {
          "Key": "hasCats",
          "Type": "Boolean",
          "Prompt": "Does this image have cats?"
        },
        {
          "Key": "dogCount",
          "Type": "Integer",
          "Prompt": "How many dogs do you see in this image?",
          "Minimum": 0
        },
        {
          "Key": "setting",
          "Type": "Enum",
          "Prompt": "Where was this taken?",
          "Options": [
            "Indoors",
            "Outdoors",
            "Unknown"
          ]
        },
        {
          "Key": "colors",
          "Type": "StringList",
          "Prompt": "List the dominant colors.",
          "MaxItems": 5
        }
      ]
    }
  },
  "IncludeProperties": true
}

{
  "Image": {
    "Data": "{{sampleImageBase64}}",
    "MediaType": "image/jpeg"
  },
  "Context": "Single string context is accepted too.",
  "Functions": {
    "Summarize": {
      "Enable": false
    },
    "Extract": {
      "Enable": true,
      "Mode": "PerField",
      "Fields": [
        {
          "Key": "hasCats",
          "Type": "Boolean",
          "Prompt": "Does this image have cats?"
        },
        {
          "Key": "dogCount",
          "Type": "Integer",
          "Prompt": "How many dogs do you see in this image?",
          "Minimum": 0
        }
      ]
    }
  }
}

{
  "Video": {
    "Url": "{{sampleVideoUrl}}"
  },
  "Context": [
    "Recorded keynote at a developer conference."
  ],
  "Functions": {
    "Summarize": {
      "Enable": true,
      "MaxWords": 150
    },
    "Extract": {
      "Enable": true,
      "Fields": [
        {
          "Key": "speakerCount",
          "Type": "Integer",
          "Prompt": "How many distinct speakers appear?"
        }
      ]
    },
    "Scenes": {
      "Enable": true,
      "FramesPerScene": 3,
      "Detection": {
        "Threshold": 0.3,
        "MinSceneMs": 2000,
        "MaxSceneMs": 60000,
        "MaxScenes": 200
      },
      "Summarize": {
        "Enable": true,
        "Style": "Caption"
      },
      "Extract": {
        "Enable": true,
        "Fields": [
          {
            "Key": "showsSlide",
            "Type": "Boolean",
            "Prompt": "Is a presentation slide visible?"
          }
        ]
      }
    },
    "Transcribe": {
      "Enable": true,
      "Language": "en"
    }
  },
  "IncludeKeyframeData": false
}

{
  "Audio": {
    "Url": "{{sampleAudioUrl}}"
  },
  "Context": [
    "Daily standup of the platform team."
  ],
  "TranscriptionModel": {
    "Endpoint": "whisper"
  },
  "TextModel": {
    "Endpoint": "ollama-gpt-oss-20b"
  },
  "Functions": {
    "Transcribe": {
      "Enable": true,
      "Language": "en"
    },
    "Summarize": {
      "Enable": true,
      "Style": "Bullets",
      "MaxWords": 120
    },
    "Extract": {
      "Enable": true,
      "Fields": [
        {
          "Key": "speakerNames",
          "Type": "StringList",
          "Prompt": "Names of the people who speak or are mentioned."
        },
        {
          "Key": "blockers",
          "Type": "Boolean",
          "Prompt": "Does anyone report a blocker?"
        }
      ]
    }
  }
}
